+static int
+hex2bin(uint8_t* out, uint8_t* out_end, char* in)
+{
+    uint8_t* out_start = out;
+    int is_low = 0;
+    int c;
+
+    while (*in != '\0')
+    {
+        c = ws_xton(*in);
+        if (c < 0)
+        {
+            in++;
+            continue;
+        }
+        if (out == out_end)
+        {
+            /* Too much data */
+            return -1;
+        }
+        if (is_low == 0)
+        {
+            *out = c << 4;
+            is_low = 1;
+        }
+        else {
+            *out |= (c & 0x0f);
+            is_low = 0;
+            out++;
+        }
+        in++;
+    }
+
+    return (int)(out - out_start);
+}

